WITH d(page,chapter_slug,topic_slug,title,body,confidence,canonical_hash) AS (VALUES ('604','europe','cis-and-soviet-history-past-questions-reference','CIS and Soviet-history — institutional and political boundary','CIS membership counts, participant classifications, Georgia/Armenia/Turkmenistan status lines, Soviet leadership, reforms, dissolution, and revolution references are historic or institutional content. Current-status inference, ideological superlatives, and corrupted options are withheld.','high','81bfb0e2abb87319b32bb72efdb3302f032c673604d5f0a0a6935c1a20d15ed8'),
('605','europe','greece-classical-reference','Greece reference — chronology and superlative boundary','The source-visible Greece panel is retained only for corroborated geography, UN status, bounded city-state context, and the teaching lineage. Its compressed chronology, first-philosophy/first-map claims, informal epithets, local-grave claim, and oversimplified etymology are withheld.','high','f1606ac656ff65d44fa4368cef55a8c538f556e0df7d7855ee0b44ea48733d53'),
('606','europe','greece-classical-reference','Classical quotation panel — exclusion boundary','Page 606 consists mainly of attributed philosophical quotations, translated aphorisms, and fragmented biographies. Those quotations and slogans are not transformed into neutral learning facts or flashcards.','high','08adb7e562c73ae8038a5a0bddf3690762120f6797c67d2fd1f59c1c5db21173'),
('607','europe','greece-historical-figures-past-questions-reference','Greek figures past questions — MCQ boundary','Only Q02, Q06, and Q07 have complete readable stems, four options, visible keys, and acceptable scope. Quotation-attribution questions and the Herodotus-birthplace question with its historically inconsistent key are withheld.','high','69bc4ecf47f347feb3f8fde8558dbdbe08291ad6234731ce943c262061bf7632'),
('608','europe','italy-reference','Italy reference — historic and geographic boundary','Italy’s 1946 transition, Rome, bounded Roman historic offices, and enclave geography are retained. The Turkey panel is unreadable; Venice-at-the-Po, founding myth, broad Roman-law/religion formulations, and informal labels are withheld rather than rewritten.','high','a5223d9ba5911d467ff86ac13c8f9cee85604688ffee06c9c09f1d81f44f28b7'),
('608','europe','italy-reference','Italy source-text recovery — local OCR limitation','The page-608 Italy panel was reconciled using local Bangla OCR against the rotated scan after the vision-model credit balance prevented further retry. Only text visible in both recovery paths is classified for import.','medium','e6d51f2740b9d0230490e42873cbecb532153d21c73ac3a5554374217e6185f1')) INSERT INTO public.gk_notes (book_id,chapter_id,topic_id,title,content,source_page,source_section,display_order,confidence,canonical_hash) SELECT b.id,c.id,t.id,d.title,d.body,d.page::integer,d.title,d.page::integer,d.confidence::confidence_level,d.canonical_hash FROM d JOIN public.books b ON b.title='Jubayer''s GK' JOIN public.chapters c ON c.book_id=b.id AND c.slug=d.chapter_slug JOIN public.topics t ON t.chapter_id=c.id AND t.slug=d.topic_slug ON CONFLICT (canonical_hash) DO UPDATE SET content=EXCLUDED.content,confidence=EXCLUDED.confidence;
