INSERT INTO public.exam_sources (name,institution,exam_type,description,normalized_name) SELECT 'University of Dhaka','University of Dhaka','admission','Normalized from printed source label on page 607.','dhaka-university' WHERE NOT EXISTS (SELECT 1 FROM public.exam_sources WHERE normalized_name='dhaka-university'); INSERT INTO public.gk_mcqs (book_id,chapter_id,topic_id,question,correct_option,explanation,source_page,source_section,source_question_number,difficulty,confidence,canonical_hash) SELECT b.id,c.id,t.id,'বীর আলেকজান্ডারের শিক্ষক কে ছিলেন?','গ','Printed key visually reviewed; verification and historic scope are recorded in the batch ledger.',607,'বিগত বছরের প্রশ্ন','07',3,'high'::confidence_level,'a5ed1c34ef6b408a44ec00a93da79d974c345edcb6cc8e7cef307f9e0afcf060' FROM public.books b JOIN public.chapters c ON c.book_id=b.id AND c.slug='europe' JOIN public.topics t ON t.chapter_id=c.id AND t.slug='greece-historical-figures-past-questions-reference' WHERE b.title='Jubayer''s GK' ON CONFLICT (canonical_hash) DO UPDATE SET correct_option=EXCLUDED.correct_option,explanation=EXCLUDED.explanation,confidence=EXCLUDED.confidence; INSERT INTO public.gk_mcq_options (mcq_id,option_key,option_text,display_order,is_correct) SELECT m.id,'ক','সফোক্রিস',1,false FROM public.gk_mcqs m WHERE m.canonical_hash='a5ed1c34ef6b408a44ec00a93da79d974c345edcb6cc8e7cef307f9e0afcf060' AND NOT EXISTS (SELECT 1 FROM public.gk_mcq_options o WHERE o.mcq_id=m.id AND o.option_key='ক');
